mapper.select:
select c.cust_id, c.cust_cd, c.cust_nm, s.trade_status
  from mst_cust c join srm_supplier s on s.cust_id = c.cust_id
 where c.cust_cd = #{custCd}

mapper.sql:
select x.*, (x.status in ('SENT', 'PARTIAL_RECEIVED') and x.open_line_cnt > 0 and x.eta_date < #{c.today}) as late
  from (select   ) x
where x.status in ('SENT', 'PARTIAL_RECEIVED') and x.open_line_cnt > 0 and x.eta_date < #{c.today}

 where a.ship_date <= #{c.to} and a.eta_date >= #{c.from}
and a.status = #{c.status}

   and (a.asn_no ilike #{c.keywordLike} escape '\' or a.supplier_ref ilike #{c.keywordLike} escape '\'
        or c.cust_cd ilike #{c.keywordLike} escape '\' or c.cust_nm ilike #{c.keywordLike} escape '\')

mapper.update:
update srm_asn
   set plant_cd = #{v.plantCd}, ship_date = #{v.shipDate}, eta_date = #{v.etaDate}, supplier_ref = #{v.supplierRef},
       carrier_memo = #{v.carrierMemo}, remark = #{v.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where asn_id = #{asnId} and status = 'DRAFT' and row_ver = #{rowVer} and cust_id = #{v.custId}

update srm_asn
   set status = 'SENT', sent_at = now(), sent_by = #{by}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where asn_id = #{asnId} and status = 'DRAFT' and row_ver = #{rowVer}

update srm_asn
   set status = #{to}, cancel_reason = #{cancelReason}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where asn_id = #{asnId} and status = #{from} and row_ver = #{rowVer}
